import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

conv3d_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#define TILE_H 16
#define TILE_W 16
#define OC_TILE 16
__global__ void conv3d_forward_kernel_tiled(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int N, int C_in, int D_in, int H_in, int W_in,
    int C_out, int D_out, int H_out, int W_out,
    int kD, int kH, int kW,
    int stride, int padding, int dilation,
    int groups, int C_in_per_group, int C_out_per_group,
    int SH, int SW, int numOcTiles,
    bool has_bias)
{
    extern __shared__ float smem[];
    float* s_input = smem;                              // C_in_per_group * SH * SW
    float* s_weight = smem + C_in_per_group * SH * SW;   // OC_TILE * C_in_per_group * kH * kW
    int w_out0 = blockIdx.x * TILE_W;
    int h_out0 = blockIdx.y * TILE_H;
    int w_out = w_out0 + threadIdx.x;
    int h_out = h_out0 + threadIdx.y;
    int z = blockIdx.z;
    int oc_tile_idx = z % numOcTiles; z /= numOcTiles;
    int group_id = z % groups; z /= groups;
    int d_out = z % D_out; z /= D_out;
    int n = z;
    int ic_start = group_id * C_in_per_group;
    int oc_start = group_id * C_out_per_group + oc_tile_idx * OC_TILE;
    int oc_count = OC_TILE;
    if (oc_tile_idx * OC_TILE + OC_TILE > C_out_per_group) {
        oc_count = C_out_per_group - oc_tile_idx * OC_TILE;
    }
    float acc[OC_TILE];
    #pragma unroll
    for (int i = 0; i < OC_TILE; ++i) acc[i] = 0.0f;
    int tid = threadIdx.y * TILE_W + threadIdx.x;
    int block_threads = TILE_W * TILE_H;
    int sinput_plane = SH * SW;
    int total_load_in = C_in_per_group * sinput_plane;
    int total_load_w = oc_count * C_in_per_group * kH * kW;
    for (int kd = 0; kd < kD; ++kd) {
        int d_in = d_out * stride - padding + kd * dilation;
        bool valid_d = (d_in >= 0 && d_in < D_in);
        for (int idx = tid; idx < total_load_in; idx += block_threads) {
            int ic = idx / sinput_plane;
            int rem = idx % sinput_plane;
            int sh = rem / SW;
            int sw = rem % SW;
            int h_in = h_out0 * stride - padding + sh;
            int w_in = w_out0 * stride - padding + sw;
            float val = 0.0f;
            if (valid_d && h_in >= 0 && h_in < H_in && w_in >= 0 && w_in < W_in) {
                int in_c = ic_start + ic;
                long off = (((long)n * C_in + in_c) * H_in + h_in) * W_in + w_in;
                off = off * D_in + d_in;
                val = input[off];
            }
            s_input[idx] = val;
        }
        for (int idx = tid; idx < total_load_w; idx += block_threads) {
            int oc_local = idx / (C_in_per_group * kH * kW);
            int rem = idx % (C_in_per_group * kH * kW);
            int ic = rem / (kH * kW);
            int rem2 = rem % (kH * kW);
            int kh = rem2 / kW;
            int kw = rem2 % kW;
            int oc = oc_start + oc_local;
            long w_off = ((long)oc * C_in_per_group + ic) * kD * kH * kW + (kd * kH + kh) * kW + kw;
            s_weight[idx] = weight[w_off];
        }
        __syncthreads();
        if (h_out < H_out && w_out < W_out) {
            int local_h = threadIdx.y * stride;
            int local_w = threadIdx.x * stride;
            for (int ic = 0; ic < C_in_per_group; ++ic) {
                const float* s_in_c = s_input + ic * sinput_plane;
                for (int kh = 0; kh < kH; ++kh) {
                    int sh = local_h + kh * dilation;
                    const float* s_in_row = s_in_c + sh * SW;
                    for (int kw = 0; kw < kW; ++kw) {
                        int sw = local_w + kw * dilation;
                        float in_val = s_in_row[sw];
                        const float* w_base = s_weight + (ic * kH + kh) * kW + kw;
                        #pragma unroll
                        for (int oc_local = 0; oc_local < OC_TILE; ++oc_local) {
                            if (oc_local < oc_count) {
                                float w_val = w_base[oc_local * C_in_per_group * kH * kW];
                                acc[oc_local] += in_val * w_val;
                            }
                        }
                    }
                }
            }
        }
        __syncthreads();
    }
    if (h_out < H_out && w_out < W_out) {
        for (int oc_local = 0; oc_local < oc_count; ++oc_local) {
            int oc = oc_start + oc_local;
            float val = acc[oc_local];
            if (has_bias) val += bias[oc];
            long out_idx = ((((long)n * C_out + oc) * H_out + h_out) * W_out + w_out) * D_out + d_out;
            output[out_idx] = val;
        }
    }
}
torch::Tensor conv3d_forward_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride,
    int padding,
    int dilation,
    int groups,
    bool has_bias)
{
    input = input.contiguous();
    weight = weight.contiguous();
    int N = input.size(0);
    int C_in = input.size(1);
    int H_in = input.size(2);
    int W_in = input.size(3);
    int D_in = input.size(4);
    int C_out = weight.size(0);
    int C_in_per_group = weight.size(1);
    int kH = weight.size(2);
    int kW = weight.size(3);
    int kD = weight.size(4);
    int C_out_per_group = C_out / groups;
    int H_out = (H_in + 2 * padding - dilation * (kH - 1) - 1) / stride + 1;
    int W_out = (W_in + 2 * padding - dilation * (kW - 1) - 1) / stride + 1;
    int D_out = (D_in + 2 * padding - dilation * (kD - 1) - 1) / stride + 1;
    auto output = torch::zeros({N, C_out, H_out, W_out, D_out}, input.options());
    int SH = (TILE_H - 1) * stride + (kH - 1) * dilation + 1;
    int SW = (TILE_W - 1) * stride + (kW - 1) * dilation + 1;
    int numOcTiles = (C_out_per_group + OC_TILE - 1) / OC_TILE;
    dim3 block(TILE_W, TILE_H);
    dim3 grid(
        (W_out + TILE_W - 1) / TILE_W,
        (H_out + TILE_H - 1) / TILE_H,
        (unsigned int)((long)N * D_out * groups * numOcTiles)
    );
    size_t shared_bytes = (size_t)(C_in_per_group * SH * SW + OC_TILE * C_in_per_group * kH * kW) * sizeof(float);
    const float* bias_ptr = has_bias ? bias.contiguous().data_ptr<float>() : nullptr;
    conv3d_forward_kernel_tiled<<<grid, block, shared_bytes>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias_ptr,
        output.data_ptr<float>(),
        N, C_in, D_in, H_in, W_in,
        C_out, D_out, H_out, W_out,
        kD, kH, kW,
        stride, padding, dilation,
        groups, C_in_per_group, C_out_per_group,
        SH, SW, numOcTiles,
        has_bias
    );
    return output;
}
"""

conv3d_cpp_source = r"""
torch::Tensor conv3d_forward_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride,
    int padding,
    int dilation,
    int groups,
    bool has_bias);
"""

conv3d_module = load_inline(
    name="conv3d_module",
    cpp_sources=conv3d_cpp_source,
    cuda_sources=conv3d_source,
    functions=["conv3d_forward_cuda"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Custom CUDA implementation of a Conv3d with kernel (kernel_size, kernel_size, 1),
    matching the semantics of nn.Conv3d given the same parameters.
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int, stride: int = 1,
                 padding: int = 0, dilation: int = 1, groups: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.dilation = dilation
        self.groups = groups
        self.has_bias = bias

        # Weight shape: (out_channels, in_channels/groups, kH, kW, kD)
        self.weight = nn.Parameter(
            torch.empty(out_channels, in_channels // groups, kernel_size, kernel_size, 1)
        )
        nn.init.kaiming_uniform_(self.weight, a=5 ** 0.5)

        if bias:
            self.bias = nn.Parameter(torch.empty(out_channels))
            fan_in = (in_channels // groups) * kernel_size * kernel_size * 1
            bound = 1 / (fan_in ** 0.5)
            nn.init.uniform_(self.bias, -bound, bound)
        else:
            self.register_parameter('bias', None)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        x = x.contiguous().cuda()
        weight = self.weight.contiguous().cuda()
        bias_tensor = self.bias.contiguous().cuda() if self.has_bias else torch.empty(0, device=x.device, dtype=x.dtype)

        out = conv3d_module.conv3d_forward_cuda(
            x, weight, bias_tensor,
            self.stride, self.padding, self.dilation, self.groups, self.has_bias
        )
        return out

