#include <cuda.h>
#include <cuda_runtime.h>

__global__ void conv3d_forward_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int N, int C_in, int D_in, int H_in, int W_in,
    int C_out, int D_out, int H_out, int W_out,
    int kD, int kH, int kW,
    int stride, int padding, int dilation,
    int groups, int C_in_per_group, int C_out_per_group,
    bool has_bias)
{
    long total = (long)N * C_out * D_out * H_out * W_out;
    long idx = blockIdx.x * (long)blockDim.x + threadIdx.x;
    if (idx >= total) return;

    // decode idx -> n, oc, h, w, d (matches output tensor layout N,C_out,H_out,W_out,D_out)
    long tmp = idx;
    int d_out = tmp % D_out; tmp /= D_out;
    int w_out = tmp % W_out; tmp /= W_out;
    int h_out = tmp % H_out; tmp /= H_out;
    int oc = tmp % C_out; tmp /= C_out;
    int n = tmp;

    int group_id = oc / C_out_per_group;
    int ic_start = group_id * C_in_per_group;

    float acc = 0.0f;

    int d_in_base = d_out * stride - padding;
    int h_in_base = h_out * stride - padding;
    int w_in_base = w_out * stride - padding;

    for (int ic = 0; ic < C_in_per_group; ++ic) {
        int in_c = ic_start + ic;
        const float* input_nc = input + (((long)n * C_in + in_c) * D_in * H_in * W_in);
        const float* weight_oc_ic = weight + (((long)oc * C_in_per_group + ic) * kD * kH * kW);

        for (int kd = 0; kd < kD; ++kd) {
            int d_in = d_in_base + kd * dilation;
            if (d_in < 0 || d_in >= D_in) continue;
            for (int kh = 0; kh < kH; ++kh) {
                int h_in = h_in_base + kh * dilation;
                if (h_in < 0 || h_in >= H_in) continue;
                for (int kw = 0; kw < kW; ++kw) {
                    int w_in = w_in_base + kw * dilation;
                    if (w_in < 0 || w_in >= W_in) continue;

                    float in_val = input_nc[((long)h_in * W_in + w_in) * D_in + d_in];
                    float w_val = weight_oc_ic[(kd * kH + kh) * kW + kw];
                    acc += in_val * w_val;
                }
            }
        }
    }

    if (has_bias) {
        acc += bias[oc];
    }

    output[idx] = acc;
}

